package app.metrolife;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import java.util.*;

/** Per-life, server-owned home furnishings. Coordinates are in metres on a quarter-metre grid. */
final class HomeDesign {
 final GameService g;final JsonNode catalog;
 HomeDesign(GameService g){this.g=g;try(var in=getClass().getResourceAsStream("/static-data/furniture.json")){catalog=g.mapper.readTree(in);}catch(Exception e){throw new IllegalStateException("Furniture catalogue missing",e);}}
 JsonNode product(String id){for(JsonNode row:catalog.path("items"))if(row.path("id").asText().equals(id))return row;throw new ApiException(400,"Choose a listed furnishing");}
 ObjectNode ensure(ObjectNode s){
  ObjectNode design;if(s.path("homeDesign") instanceof ObjectNode saved)design=saved;else{design=s.putObject("homeDesign").put("revision",0).put("wallColor","#e5d8bf").put("floorColor","#ad8b69").put("width",7).put("depth",6);ArrayNode items=design.putArray("items");starter(items,"bed","starter-bed",2.25,-1.65);starter(items,"stove","starter-stove",-2.7,.1);starter(items,"shower","starter-shower",-2.7,-1.9);starter(items,"couch","starter-chair",1.75,1);}
  double rent=s.path("home").path("rent").asDouble();double w=rent>=300?12:rent>=150?10:rent>=80?8.5:7,d=rent>=300?10:rent>=150?8:rent>=80?7:6;design.put("width",Math.max(w,design.path("width").asDouble(7))).put("depth",Math.max(d,design.path("depth").asDouble(6)));return design;
 }
 void starter(ArrayNode rows,String id,String catalogId,double x,double z){rows.addObject().put("id",id).put("catalogId",catalogId).put("x",x).put("z",z).put("rotation",0).put("paid",product(catalogId).path("price").asInt());}
 ObjectNode owner(String room){if(room==null||!room.startsWith("home:"))return null;String uid=room.substring(5);for(JsonNode row:g.table("sims"))if(row.path("userId").asText().equals(uid))return (ObjectNode)row;return null;}
 JsonNode layout(String city,String room){ObjectNode s=owner(room);return s==null?g.navigation.layout(city,"home"):layout(s,ensure(s));}
 ObjectNode layout(ObjectNode s,JsonNode design){
  double w=design.path("width").asDouble(7),d=design.path("depth").asDouble(6);ObjectNode out=g.object().put("name","Your home").put("revision",design.path("revision").asInt()).put("wallColor",design.path("wallColor").asText()).put("floorColor",design.path("floorColor").asText());out.putObject("bounds").put("w",w).put("d",d);out.putObject("exit").put("x",0).put("z",d/2-.7);ArrayNode furniture=out.putArray("furniture"),boxes=out.putArray("boxes"),slots=out.putArray("slots"),stations=out.putArray("stations");
  for(JsonNode item:design.path("items")){JsonNode p=product(item.path("catalogId").asText());double x=item.path("x").asDouble(),z=item.path("z").asDouble(),a=item.path("rotation").asInt()*Math.PI/2,pw=p.path("w").asDouble(),pd=p.path("d").asDouble();String id=item.path("id").asText(),action=p.path("action").asText(),kind=p.path("kind").asText();ObjectNode f=furniture.addObject().put("id",id).put("catalogId",p.path("id").asText()).put("kind",kind).put("color",p.path("color").asText()).put("x",x).put("z",z).put("w",pw).put("d",pd).put("angle",a);f.set("stats",p.path("stats").deepCopy());ArrayNode own=f.putArray("slots");
   if(!kind.equals("rug"))boxes.addObject().put("x",x).put("z",z).put("w",pw).put("d",pd).put("a",a);
   if(!action.isEmpty()){double reach=pd/2+.65,ax=x+Math.sin(a)*reach,az=z+Math.cos(a)*reach;if(id.equals("bed")&&x==2.25&&z==-1.65&&a==0){ax=.75;az=-1.65;}else if(id.equals("stove")&&x==-2.7&&z==.1&&a==0){ax=-1.2;az=.1;}else if(id.equals("shower")&&x==-2.7&&z==-1.9&&a==0){ax=-1.2;az=-1.9;}else if(id.equals("couch")&&x==1.75&&z==1&&a==0){ax=1;az=1;}String slotId=id.equals("couch")?"chair":id;ObjectNode slot=g.object().put("id",slotId).put("station",id).put("action",action).put("pose",action.equals("sleep")?"Sleep":action.equals("invite")?"Sit":"Interact").put("x",x).put("z",z).put("face",a+Math.PI).put("y",action.equals("sleep")?.78:action.equals("invite")?.48:0);if(action.equals("cook")||action.equals("shower")){slot.put("x",ax).put("z",az);}own.add(slot);slots.add(slot.deepCopy());stations.addObject().put("id",id).put("name",p.path("name").asText()).put("action",action).put("x",ax).put("z",az).put("face",a+Math.PI);}
  }return out;
 }
 boolean stand(JsonNode layout,double x,double z){if(Math.abs(x)>=layout.path("bounds").path("w").asDouble()/2-.25||Math.abs(z)>=layout.path("bounds").path("d").asDouble()/2-.25)return false;for(JsonNode b:layout.path("boxes"))if(Navigation.box(x,z,b,.3))return false;return true;}
 String validate(ObjectNode s,ObjectNode design){JsonNode layout=layout(s,design);double hw=design.path("width").asDouble()/2,hd=design.path("depth").asDouble()/2;List<JsonNode> rows=new ArrayList<>();design.path("items").forEach(rows::add);
  for(int i=0;i<rows.size();i++){JsonNode row=rows.get(i),p=product(row.path("catalogId").asText());double x=row.path("x").asDouble(),z=row.path("z").asDouble(),a=row.path("rotation").asInt()%2==0?p.path("w").asDouble():p.path("d").asDouble(),b=row.path("rotation").asInt()%2==0?p.path("d").asDouble():p.path("w").asDouble();if(Math.abs(x)+a/2>hw-.1||Math.abs(z)+b/2>hd-.1)return "Keep the furnishing inside your home";if(Math.abs(x)<a/2+.8&&Math.abs(z-(hd-.7))<b/2+.8)return "Keep the doorway clear";
   if(!p.path("kind").asText().equals("rug"))for(int j=0;j<i;j++){JsonNode other=rows.get(j),q=product(other.path("catalogId").asText());if(q.path("kind").asText().equals("rug"))continue;double qw=other.path("rotation").asInt()%2==0?q.path("w").asDouble():q.path("d").asDouble(),qd=other.path("rotation").asInt()%2==0?q.path("d").asDouble():q.path("w").asDouble();if(Math.abs(x-other.path("x").asDouble())<(a+qw)/2+.02&&Math.abs(z-other.path("z").asDouble())<(b+qd)/2+.02)return "Furnishings cannot overlap";}
  }
  JsonNode exit=layout.path("exit");if(!stand(layout,exit.path("x").asDouble(),exit.path("z").asDouble()))return "Keep the doorway clear";
  Set<String> reachable=new HashSet<>();ArrayDeque<double[]> queue=new ArrayDeque<>();double ex=exit.path("x").asDouble(),ez=exit.path("z").asDouble();queue.add(new double[]{ex,ez});reachable.add("0:0");while(!queue.isEmpty()){double[] at=queue.remove();int ix=(int)Math.round((at[0]-ex)/.25),iz=(int)Math.round((at[1]-ez)/.25);for(int[] dir:new int[][]{{1,0},{-1,0},{0,1},{0,-1}}){int nx=ix+dir[0],nz=iz+dir[1];String key=nx+":"+nz;if(reachable.contains(key))continue;double px=ex+nx*.25,pz=ez+nz*.25;if(stand(layout,px,pz)){reachable.add(key);queue.add(new double[]{px,pz});}}}
  for(JsonNode station:layout.path("stations")){double x=station.path("x").asDouble(),z=station.path("z").asDouble();if(!stand(layout,x,z))return "Leave room in front of every furnishing";boolean near=false;for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++){int ix=(int)Math.round((x-ex)/.25)+dx,iz=(int)Math.round((z-ez)/.25)+dz;if(reachable.contains(ix+":"+iz))near=true;}if(!near)return "Keep a walking route to every furnishing";}
  return "";
 }
 ObjectNode recoveryBonus(ObjectNode s,String action){ObjectNode bonus=g.object();ObjectNode design=ensure(s);double comfort=0,fun=0,hygiene=0,environment=0;String selected=s.path("activitySlot").path("station").asText();for(JsonNode item:design.path("items")){JsonNode p=product(item.path("catalogId").asText()),stats=p.path("stats");environment+=stats.path("environment").asDouble();if(item.path("id").asText().equals(selected)||selected.isEmpty()&&p.path("action").asText().equals(action)){comfort=Math.max(comfort,stats.path("comfort").asDouble());fun=Math.max(fun,stats.path("fun").asDouble());hygiene=Math.max(hygiene,stats.path("hygiene").asDouble());}}if(action.equals("sleep"))bonus.put("energy",comfort*1.5);if(action.equals("cook"))bonus.put("hunger",fun);if(action.equals("shower"))bonus.put("energy",hygiene*.5);if(action.equals("invite"))bonus.put("social",comfort).put("fun",fun);bonus.put("fun",bonus.path("fun").asDouble()+Math.min(8,environment*.2));return bonus;}
 ObjectNode read(String token){ObjectNode ses=g.session(token,true),s=g.sim(ses),w=g.world(ses);g.decay(s,w);ensure(s);g.store.save();return response(s,w);}
 ObjectNode response(ObjectNode s,ObjectNode w){ObjectNode out=g.simResponse(s,w);out.set("catalog",catalog.deepCopy());out.set("design",ensure(s).deepCopy());out.set("layout",layout(s,ensure(s)));return out;}
 ObjectNode mutate(String token,JsonNode body){ObjectNode ses=g.session(token,true),s=g.sim(ses),w=g.world(ses);g.decay(s,w);GameService.require(s.path("position").path("room").asText().equals("home:"+s.path("userId").asText()),409,"Go inside your own home to decorate");g.navigation.idle(s);ObjectNode design=ensure(s).deepCopy();String op=body.path("op").asText();ArrayNode rows=design.withArray("items");double charge=0;String label="Home decoration";
  if(op.equals("paint")){for(String field:List.of("wallColor","floorColor"))if(body.has(field)){boolean valid=false;for(JsonNode color:catalog.path(field.equals("wallColor")?"wallColors":"floorColors"))if(color.asText().equals(body.path(field).asText()))valid=true;GameService.require(valid,400,"Choose a listed paint colour");design.put(field,body.path(field).asText());}charge=20;label="Wall and floor finish";}
  else{ObjectNode row=null;int index=-1;for(int i=0;i<rows.size();i++)if(rows.get(i).path("id").asText().equals(body.path("id").asText())){row=(ObjectNode)rows.get(i);index=i;}
   if(op.equals("buy")){JsonNode p=product(body.path("catalogId").asText());GameService.require(rows.size()<80,409,"Your home can hold up to 80 furnishings");row=rows.addObject().put("id",g.id()).put("catalogId",p.path("id").asText()).put("paid",p.path("price").asInt());charge=p.path("price").asDouble();label="Furniture: "+p.path("name").asText();}
   else GameService.require(row!=null,404,"Choose one of your furnishings");
   if(op.equals("sell")){charge=-Math.floor(row.path("paid").asDouble()*.6);label="Furniture sale";rows.remove(index);}
   else{GameService.require(op.equals("buy")||op.equals("move"),400,"Choose buy, move, sell or paint");for(String field:List.of("x","z")){double value=body.path(field).asDouble(Double.NaN);GameService.require(Double.isFinite(value)&&Math.abs(value*4-Math.rint(value*4))<.00001,400,"Place furniture on the quarter-metre grid");row.put(field,value);}int rotation=body.path("rotation").asInt();GameService.require(rotation>=0&&rotation<4,400,"Choose one of four rotations");row.put("rotation",rotation);}
  }
  String invalid=validate(s,design);GameService.require(invalid.isEmpty(),409,invalid);GameService.require(charge<=s.path("cash").asDouble(),402,"Not enough money for this furnishing");if(charge>50)GameService.require(body.path("confirm").asBoolean(),400,"Confirm this furniture purchase");if(charge>=0)g.property.pay(s,charge,label);else g.economy.credit(s,-charge,label);design.put("revision",design.path("revision").asInt()+1);s.set("homeDesign",design);s.putNull("activitySlot");JsonNode layout=layout(s,design);ObjectNode at=g.navigation.position(s);if(!stand(layout,at.path("x").asDouble(),at.path("z").asDouble()))at.put("x",layout.path("exit").path("x").asDouble()).put("z",layout.path("exit").path("z").asDouble());g.store.save();return response(s,w).put("message",label);
 }
}
